/**
 * Restore LoTrinh-Bootstrap5-UI.{data,detail,app}.js from agent transcript
 * and merge to LoTrinh-Bootstrap5-UI.js with UTF-8.
 */
var fs = require('fs');
var path = require('path');

var transcriptPath = 'C:/Users/trong/.cursor/projects/g-0-LMS-V2-HeSinhThai-hos/agent-transcripts/9e27414d-b6d3-4320-86f2-d66cb490f568/9e27414d-b6d3-4320-86f2-d66cb490f568.jsonl';
var outDir = 'g:/0.LMS/V2-HeSinhThai/hos/Docs';

var targetFiles = {
  'LoTrinh-Bootstrap5-UI.data.js': null,
  'LoTrinh-Bootstrap5-UI.detail.js': null,
  'LoTrinh-Bootstrap5-UI.app.js': null
};

function normPath(p) {
  if (!p) return '';
  return p.replace(/\\/g, '/').split('/').pop().toLowerCase();
}

function applyReplace(content, oldString, newString, replaceAll) {
  if (replaceAll) {
    return content.split(oldString).join(newString);
  }
  var idx = content.indexOf(oldString);
  if (idx < 0) {
    console.warn('StrReplace miss:', oldString.substring(0, 60).replace(/\n/g, '\\n'));
    return content;
  }
  return content.substring(0, idx) + newString + content.substring(idx + oldString.length);
}

var lines = fs.readFileSync(transcriptPath, 'utf8').split(/\r?\n/);
var opCount = 0;

lines.forEach(function (line, li) {
  if (!line.trim()) return;
  var obj;
  try { obj = JSON.parse(line); } catch (e) { return; }
  var content = obj.message && obj.message.content;
  if (!content || !Array.isArray(content)) return;

  content.forEach(function (part) {
    if (part.type !== 'tool_use') return;
    var input = part.input || {};
    var filePath = input.path || '';
    var base = normPath(filePath);
    var key = null;
    Object.keys(targetFiles).forEach(function (k) {
      if (base === k.toLowerCase()) key = k;
    });
    if (!key) return;

    if (part.name === 'Write' && typeof input.contents === 'string') {
      targetFiles[key] = input.contents;
      opCount++;
      console.log('Write', key, 'line', li + 1, 'len', input.contents.length);
    } else if (part.name === 'StrReplace' && targetFiles[key] !== null) {
      targetFiles[key] = applyReplace(
        targetFiles[key],
        input.old_string,
        input.new_string,
        !!input.replace_all
      );
      opCount++;
      console.log('StrReplace', key, 'line', li + 1);
    }
  });
});

Object.keys(targetFiles).forEach(function (k) {
  if (targetFiles[k] === null) {
    console.error('MISSING:', k);
    process.exit(1);
  }
  var outPath = path.join(outDir, k);
  fs.writeFileSync(outPath, targetFiles[k], 'utf8');
  console.log('Wrote', outPath, targetFiles[k].length, 'bytes');
});

var merged = [
  '/* CMS L\u1ed9 tr\u00ecnh Bootstrap 5 - ECO LMS (data + detail + app) */',
  targetFiles['LoTrinh-Bootstrap5-UI.data.js'],
  targetFiles['LoTrinh-Bootstrap5-UI.detail.js'],
  targetFiles['LoTrinh-Bootstrap5-UI.app.js']
].join('\n\n');

var mergedPath = path.join(outDir, 'LoTrinh-Bootstrap5-UI.js');
fs.writeFileSync(mergedPath, merged, 'utf8');
console.log('Wrote merged', mergedPath, merged.length, 'bytes');

var sample = merged.match(/weeks: "([^"]+)"/);
console.log('Sample weeks:', sample && sample[1]);
console.log('Has Tu\u1ea7n 1:', merged.indexOf('Tu\u1ea7n 1') >= 0);
console.log('Has L\u1ed9 tr\u00ecnh:', merged.indexOf('L\u1ed9 tr\u00ecnh') >= 0);
console.log('Total ops applied:', opCount);

